SET NAMES utf8mb4;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,username VARCHAR(100) NOT NULL UNIQUE,email VARCHAR(190),password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'employee',permissions JSON,active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE app_settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value LONGTEXT NOT NULL,updated_by BIGINT UNSIGNED,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_settings_user FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,last_used_at DATETIME DEFAULT CURRENT_TIMESTAMP,user_agent VARCHAR(255),ip_address VARCHAR(45),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_sessions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL,ip_address VARCHAR(45) NOT NULL,attempted_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE password_reset_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,username VARCHAR(100) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,request_ip VARCHAR(45),expires_at DATETIME NOT NULL,used_at DATETIME,requested_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE process_documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,process_id VARCHAR(50) NOT NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(100) NOT NULL UNIQUE,mime_type VARCHAR(100) NOT NULL,file_size INT UNSIGNED NOT NULL,uploaded_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_docs_user FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE email_report_recipients(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE scheduled_report_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,report_date DATE NOT NULL,report_type VARCHAR(60) NOT NULL,status VARCHAR(30) NOT NULL,recipients TEXT,error_message TEXT,sent_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_report(report_date,report_type)) ENGINE=InnoDB;
CREATE TABLE cheque_notification_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,stock_id VARCHAR(80) NOT NULL,process_id VARCHAR(80),cheque_number VARCHAR(120) NOT NULL,notification_type VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,error_message TEXT,sent_by BIGINT UNSIGNED,sent_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_cheque_user FOREIGN KEY(sent_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
